#include "observatory/observatory.h"
#include <stdio.h>
#include <stdlib.h>
#define CHECK(c) do { if(!(c)){fprintf(stderr,"CHECK failed %s:%d: %s\n",__FILE__,__LINE__,#c);exit(EXIT_FAILURE);} }while(0)
static observatory_task_config_t cfg(uint16_t id,uint32_t p,uint32_t d,uint32_t b,uint32_t st){observatory_task_config_t c={id,p,d,b,st};return c;}
static void test_stats(void){observatory_t o;observatory_snapshot_t s;observatory_init(&o);CHECK(observatory_register_task(&o,cfg(1,10,8,6,16),0));CHECK(!observatory_register_task(&o,cfg(1,10,8,6,16),0));CHECK(!observatory_register_task(&o,cfg(2,0,8,6,16),0));CHECK(observatory_record_job(&o,1,1,5,32));CHECK(observatory_record_job(&o,1,11,17,32));CHECK(observatory_get_snapshot(&o,1,&s));CHECK(s.sample_count==2&&s.completed_jobs==2);CHECK(s.execution_min_ticks==4&&s.execution_max_ticks==6&&s.execution_average_ticks==5);CHECK(s.deadline_misses==0&&s.execution_budget_violations==0);}
static void test_fault_flags(void){observatory_t o;observatory_snapshot_t s;observatory_init(&o);CHECK(observatory_register_task(&o,cfg(7,10,5,3,10),0));CHECK(observatory_record_job(&o,7,1,7,4));CHECK(observatory_get_snapshot(&o,7,&s));CHECK(s.deadline_misses==1&&s.execution_budget_violations==1&&s.stack_warnings==1);CHECK((s.event_flags&OBS_EVENT_DEADLINE_MISS)!=0);CHECK((s.event_flags&OBS_EVENT_EXEC_BUDGET)!=0);CHECK((s.event_flags&OBS_EVENT_STACK_WARNING)!=0);observatory_clear_events(&o,7,OBS_EVENT_STACK_WARNING);CHECK((observatory_event_flags(&o,7)&OBS_EVENT_STACK_WARNING)==0);}
static void test_wrap(void){observatory_t o;observatory_snapshot_t s;observatory_init(&o);CHECK(observatory_register_task(&o,cfg(4,20,10,10,0),UINT32_MAX-5U));CHECK(observatory_record_job(&o,4,UINT32_MAX-4U,3U,100U));CHECK(observatory_get_snapshot(&o,4,&s));CHECK(s.sample_count==1&&s.execution_max_ticks==8&&s.deadline_misses==0);}
static void test_invalid_and_capacity(void){observatory_t o;observatory_snapshot_t s;uint16_t i;observatory_init(&o);CHECK(observatory_register_task(&o,cfg(5,10,8,6,0),0));CHECK(!observatory_record_job(&o,5,0,0x80000000U,0));CHECK((observatory_event_flags(&o,5)&OBS_EVENT_INVALID_SAMPLE)!=0);CHECK(!observatory_get_snapshot(&o,99,&s));CHECK(!observatory_record_stack(&o,99,0));observatory_init(&o);for(i=0;i<OBSERVATORY_MAX_TASKS;i++)CHECK(observatory_register_task(&o,cfg((uint16_t)(100+i),10,5,4,0),0));CHECK(!observatory_register_task(&o,cfg(999,10,5,4,0),0));}
int main(void){test_stats();test_fault_flags();test_wrap();test_invalid_and_capacity();puts("All observatory tests passed.");return EXIT_SUCCESS;}
